struct Cfg { float mapX, mapY, width, height, thisC, adjC; int layers; int preexisting; int capacity; };

// reference model of the walk
static int Model(const Cfg& c, Ev* ev, long* keys, const Node** n1s, const Node** n2s, int& nk)
{
    int n = 0; nk = 0;
